// CSRF 防护：SameSite 语义 + 双提交（double-submit）CSRF Token
// 浏览器是否在跨站请求上携带 Cookie（简化模型，语义正确）
function cookieSentOnCrossSite(sameSite, method) {
  if (sameSite === 'Strict') return false;                       // 任何跨站请求都不带
  if (sameSite === 'Lax') return method === 'GET';               // 仅顶层导航 GET 携带
  if (sameSite === 'None') return true;                          // 跨站也携带（须配 Secure）
  return false;
}
// 服务端对待办请求的判定：Cookie 是否到达 + 双提交 token 是否与 Cookie 里的一致
function serverAccepts(cookieArrived, cookieToken, headerToken, hasCsrfCheck) {
  if (!cookieArrived) return { ok: false, status: 401, reason: 'no-session-cookie' };
  if (!hasCsrfCheck) return { ok: true, status: 200, reason: 'state-changing-without-csrf-token' };
  if (!headerToken || headerToken !== cookieToken) {
    return { ok: false, status: 403, reason: 'csrf-token-mismatch' };
  }
  return { ok: true, status: 200, reason: 'csrf-ok' };
}

const TOKEN = 'csrf-abc123';
// 攻击：恶意站点让受害者浏览器发跨站 POST /transfer
function attack(name, sameSite, hasCsrfCheck) {
  const arrived = cookieSentOnCrossSite(sameSite, 'POST');
  // 攻击者无法读到受害者的 CSRF token，header 里带的是一个错值
  const r = serverAccepts(arrived, arrived ? TOKEN : null, 'attacker-guess', hasCsrfCheck);
  console.log(name + ' cookie_arrived=' + arrived + ' status=' + r.status + ' reason=' + r.reason);
}
attack('attack_samesite_strict', 'Strict', true);
attack('attack_samesite_lax', 'Lax', true);
attack('attack_samesite_none_no_csrf_check', 'None', false);   // 真实漏洞：None + 无 token 校验
attack('attack_samesite_none_with_csrf_check', 'None', true);
console.log('strict_blocks_cross_site_post=' + (cookieSentOnCrossSite('Strict', 'POST') === false));
console.log('lax_blocks_cross_site_post=' + (cookieSentOnCrossSite('Lax', 'POST') === false));
console.log('lax_allows_top_level_get=' + (cookieSentOnCrossSite('Lax', 'GET') === true));
console.log('double_submit_ok_case=' + serverAccepts(true, TOKEN, TOKEN, true).ok);
